            var geometryModel = new EngineeringDrawingModel(); geometryModel.RoadLabels.Add(new TextEvidence { SourceHandle="R1", SourceLayer="ROAD", RawText="ROAD C.L.", PositionX=5, PositionY=2 }); geometryModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="B1", SourceLayer="BOUNDARY", RawText="UNIT LIMIT", PositionX=5, PositionY=100 });
            var capture = new PlotGeometryCapture(); capture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle="R1", SourceLayer="ROAD", PositionX=5, PositionY=2, Height=1 }); capture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle="B1", SourceLayer="BOUNDARY", PositionX=5, PositionY=100, Height=0 }); capture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="G1", SourceLayer="road", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=0,Y=0},new PlotGeometryVertex{X=10,Y=0}} }); capture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="G2", SourceLayer="ROAD", GeometryKind="Polyline", Closed=true, Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=0,Y=10},new PlotGeometryVertex{X=10,Y=10},new PlotGeometryVertex{X=10,Y=20}} });
            PlotGeometryModel geo = PlotGeometryBuilder.Build(geometryModel, capture); Assert(geo.Associations.Single(x=>x.LabelSourceHandle=="R1").Status=="Resolved" && geo.Associations.Single(x=>x.LabelSourceHandle=="R1").SelectedGeometryHandle=="G1", "Line/same-layer geometry association failed."); Assert(geo.Associations.Single(x=>x.LabelSourceHandle=="B1").Status=="Missing" && geo.Associations.Single(x=>x.LabelSourceHandle=="B1").Reason=="NoSupportedSameLayerGeometry", "Missing geometry association failed."); Assert(geo.Statistics.RoadAssociationCount+geo.Statistics.BoundaryAssociationCount==geo.Statistics.GeometryAssociationCount, "Geometry statistics invariant failed.");
            var geoQa = QaEngine.Evaluate(plotIndex, BuiltInQaRules.All, new PlotPlanModel { Geometry = geo }, BuiltInPlotPlanQaRules.All); Assert(geoQa.RuleResults.Count==15 && geoQa.RuleResults.Single(x=>x.RuleId=="PP-GEO-001").FindingCount==1 && geoQa.RuleResults.Single(x=>x.RuleId=="PP-GEO-002").FindingCount==0, "Geometry QA rules failed.");

            var spatialModel = new EngineeringDrawingModel();
            spatialModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="BN", SourceLayer="BOUNDARY-TEXT", RawText="UNIT LIMIT N. 50", PositionX=5, PositionY=51 });
            spatialModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="BE", SourceLayer="BOUNDARY-TEXT", RawText="UNIT LIMIT E 100", PositionX=101, PositionY=5 });
            spatialModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="BX", SourceLayer="BOUNDARY-TEXT", RawText="UNIT LIMIT", PositionX=0, PositionY=0 });
            spatialModel.RoadLabels.Add(new TextEvidence { SourceHandle="RE", SourceLayer="ROAD-TEXT", RawText="ROAD C.L. E 200", PositionX=201, PositionY=5 });
            spatialModel.RoadLabels.Add(new TextEvidence { SourceHandle="RX", SourceLayer="ROAD-TEXT", RawText="ROAD C.L.", PositionX=0, PositionY=0 });
            var spatialCapture = new PlotGeometryCapture();
            foreach (string handle in new[] { "BN", "BE", "BX", "RE", "RX" }) spatialCapture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle=handle, SourceLayer="TEXT", PositionX=handle=="BN" ? 5 : handle=="RE" ? 201 : 101, PositionY=handle=="BN" ? 51 : 5, Height=1 });
            spatialCapture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="HN", SourceLayer="OTHER", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=0,Y=50},new PlotGeometryVertex{X=10,Y=50}} });
            spatialCapture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="VE", SourceLayer="OTHER", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=100,Y=0},new PlotGeometryVertex{X=100,Y=10}} });
            spatialCapture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="VR", SourceLayer="OTHER", GeometryKind="Polyline", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=200,Y=0},new PlotGeometryVertex{X=200,Y=10},new PlotGeometryVertex{X=205,Y=10}} });
            spatialCapture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="ZERO", SourceLayer="OTHER", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=100,Y=5},new PlotGeometryVertex{X=100,Y=5}} });
            var spatial = PlotSpatialBuilder.Build(spatialModel, spatialCapture);
            Assert(spatial.Count==3 && spatial.All(x=>x.ConstraintId.StartsWith("spatial-constraint:", StringComparison.Ordinal)), "Strict spatial constraint parsing failed.");
            Assert(spatial.Single(x=>x.LabelSourceHandle=="BN").Axis=="N" && spatial.Single(x=>x.LabelSourceHandle=="BN").CoordinateValue==50m && spatial.Single(x=>x.LabelSourceHandle=="BN").SelectedGeometryHandle=="HN", "Northing spatial matching or cross-layer policy failed.");
            Assert(spatial.Single(x=>x.LabelSourceHandle=="BE").Axis=="E" && spatial.Single(x=>x.LabelSourceHandle=="BE").CoordinateValue==100m && spatial.Single(x=>x.LabelSourceHandle=="BE").SelectedGeometryHandle=="VE", "Easting spatial matching failed.");
            Assert(spatial.Single(x=>x.LabelSourceHandle=="RE").SelectedGeometryHandle=="VR" && spatial.Single(x=>x.LabelSourceHandle=="RE").SelectedSegmentIndex==0, "Polyline spatial matching failed.");
            spatialCapture.Primitives.Add(new PlotGeometryPrimitive { SourceHandle="VE2", SourceLayer="OTHER", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=100,Y=0},new PlotGeometryVertex{X=100,Y=10}} });
            var ambiguousSpatial = PlotSpatialBuilder.Build(spatialModel, spatialCapture); Assert(ambiguousSpatial.Single(x=>x.LabelSourceHandle=="BE").Status=="Ambiguous" && ambiguousSpatial.Single(x=>x.LabelSourceHandle=="BE").Candidates.Count==2 && string.IsNullOrEmpty(ambiguousSpatial.Single(x=>x.LabelSourceHandle=="BE").SelectedGeometryHandle), "Spatial ambiguity handling failed.");
            var missingModel = new EngineeringDrawingModel(); missingModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="M", SourceLayer="X", RawText="UNIT LIMIT E 999", PositionX=0, PositionY=0 }); var missingCapture = new PlotGeometryCapture(); missingCapture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle="M", Height=1 }); var missingSpatial = PlotSpatialBuilder.Build(missingModel, missingCapture); Assert(missingSpatial.Single().Status=="Missing" && missingSpatial.Single().Reason=="NoGeometryMatchingExplicitCoordinate", "Spatial missing behavior failed.");
            var spatialGeo = new PlotGeometryModel { SpatialConstraints = ambiguousSpatial }; var spatialQa = QaEngine.Evaluate(plotIndex, BuiltInQaRules.All, new PlotPlanModel { Geometry = spatialGeo }, BuiltInPlotPlanQaRules.All); Assert(spatialQa.RuleResults.Single(x=>x.RuleId=="PP-SPAT-001").FindingCount==0 && spatialQa.RuleResults.Single(x=>x.RuleId=="PP-SPAT-002").FindingCount==1 && spatialQa.RuleResults.Single(x=>x.RuleId=="PP-SPAT-002").EvaluatedSubjectCount==3, "Spatial QA rules failed.");
            var strictBoundary = SpatialConstraints("Boundary", "UNIT LIMIT E 1505000", new System.Collections.Generic.List<PlotGeometryPrimitive>()); Assert(strictBoundary.Single().Axis=="E" && strictBoundary.Single().CoordinateValue==1505000m, "Strict Boundary parser failed.");
            var strictRoad = SpatialConstraints("Road", "ROAD C L N. 123.5", new System.Collections.Generic.List<PlotGeometryPrimitive>()); Assert(strictRoad.Single().Axis=="N" && strictRoad.Single().CoordinateValue==123.5m, "Strict Road parser failed.");
            Assert(SpatialConstraints("Boundary", "unit limit e -12.5", new System.Collections.Generic.List<PlotGeometryPrimitive>()).Single().CoordinateValue==-12.5m, "Invariant signed decimal parsing failed.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100 EXTRA", new System.Collections.Generic.List<PlotGeometryPrimitive>()).Count==0 && SpatialConstraints("Road", "ROAD C.L.", new System.Collections.Generic.List<PlotGeometryPrimitive>()).Count==0, "Full-string spatial parsing failed.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("H",0,0,200,0) }).Single().Status=="Missing", "Horizontal Easting segment was accepted.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("D",99,0,101,10) }).Single().Status=="Missing", "Diagonal Easting segment was accepted.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT N 50", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("V",0,40,0,60) }).Single().Status=="Missing", "Vertical Northing segment was accepted.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("WITHIN",100.0005,0,100.0005,10) }).Single().Status=="Resolved", "Coordinate tolerance match failed.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("OUTSIDE",100.002,0,100.002,10) }).Single().Status=="Missing", "Coordinate tolerance rejection failed.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("ZERO",100,0,100,0) }).Single().Status=="Missing", "Zero-length segment was accepted.");
            Assert(SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("FAR",100,100,100,110) }).Single().Status=="Missing", "Distant spatial candidate was retained.");
            var ordered = SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("Z",100,0,100,10), Line("A",100,0,100,10) }); var reversedSpatial = SpatialConstraints("Boundary", "UNIT LIMIT E 100", new System.Collections.Generic.List<PlotGeometryPrimitive>{ Line("A",100,0,100,10), Line("Z",100,0,100,10) }); Assert(ordered.Single().Status=="Ambiguous" && ordered.Single().Candidates.Select(x=>x.SourceHandle).SequenceEqual(reversedSpatial.Single().Candidates.Select(x=>x.SourceHandle)) && ordered.Single().Candidates.Select(x=>x.SourceHandle).SequenceEqual(new[]{"A","Z"}), "Spatial candidate ordering determinism failed.");
            var spatialDuplicateModel = new EngineeringDrawingModel(); spatialDuplicateModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="DUP", RawText="UNIT LIMIT E 100" }); spatialDuplicateModel.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="DUP", RawText="UNIT LIMIT E 100" }); var duplicateCapture = new PlotGeometryCapture(); duplicateCapture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle="DUP", Height=1 }); Assert(PlotSpatialBuilder.Build(spatialDuplicateModel, duplicateCapture).Count==1, "Duplicate identical spatial constraint was not collapsed.");
            spatialDuplicateModel.BoundaryLabels[1].RawText="UNIT LIMIT E 101"; bool conflictThrown=false; try { PlotSpatialBuilder.Build(spatialDuplicateModel, duplicateCapture); } catch (InvalidOperationException) { conflictThrown=true; } Assert(conflictThrown, "Conflicting duplicate spatial constraint did not fail.");
            var spatialPlan = PlotPlanBuilder.Build(new EngineeringEntityIndex(), spatialModel, new DrawingSnapshot(), spatialCapture); Assert(spatialPlan.Geometry.Statistics.SpatialConstraintCount==3 && spatialPlan.Geometry.Statistics.ResolvedSpatialConstraintCount==2 && spatialPlan.Geometry.Statistics.AmbiguousSpatialConstraintCount==1 && spatialPlan.Geometry.Statistics.MissingSpatialConstraintCount==0, "Spatial statistics construction failed.");
            var missingQa = QaEngine.Evaluate(plotIndex, BuiltInQaRules.All, new PlotPlanModel { Geometry = new PlotGeometryModel { SpatialConstraints = missingSpatial } }, BuiltInPlotPlanQaRules.All); Assert(missingQa.RuleResults.Single(x=>x.RuleId=="PP-SPAT-001").FindingCount==1 && missingQa.RuleResults.Single(x=>x.RuleId=="PP-SPAT-002").FindingCount==0, "Missing spatial QA rule failed.");
            ProfileTests.Run();
            MeasurementTests.Run();
            ClearanceTests.Run();
            Console.WriteLine("All EngiSentry M2.2 through M5.0 tests passed.");
            return 0;
        }

        private static string SerializeIndex(EngineeringEntityIndex index)
        {
            var serializer = new DataContractJsonSerializer(typeof(EngineeringEntityIndex)); using (var stream = new MemoryStream()) { serializer.WriteObject(stream, index); return Encoding.UTF8.GetString(stream.ToArray()); }
        }
        private static EquipmentOccurrence Occ(string handle, string role) { return new EquipmentOccurrence { SourceHandle = handle, Role = role }; }
        private static EquipmentListLink Link(string[] handles, string description, string installation) { return new EquipmentListLink { SourceTag = "E-200-100", Description = description, Installation = installation, SourceHandles = handles.ToList(), LinkMethod = "ExactNormalizedTag" }; }
        private static PlotGeometryPrimitive Line(string handle, double x1, double y1, double x2, double y2) { return new PlotGeometryPrimitive { SourceHandle=handle, SourceLayer="ANY", GeometryKind="Line", Vertices=new System.Collections.Generic.List<PlotGeometryVertex>{new PlotGeometryVertex{X=x1,Y=y1},new PlotGeometryVertex{X=x2,Y=y2}} }; }
        private static System.Collections.Generic.List<SpatialCoordinateConstraint> SpatialConstraints(string kind, string raw, System.Collections.Generic.List<PlotGeometryPrimitive> primitives)
        {
            var model = new EngineeringDrawingModel(); if (kind=="Road") model.RoadLabels.Add(new TextEvidence { SourceHandle="S", RawText=raw, PositionX=100, PositionY=0 }); else model.BoundaryLabels.Add(new BoundaryEvidence { SourceHandle="S", RawText=raw, PositionX=100, PositionY=0 });
            var capture = new PlotGeometryCapture { Primitives=primitives }; capture.ModelSpaceTextSources.Add(new PlotTextSourceRecord { SourceHandle="S", Height=1, PositionX=100, PositionY=0 }); return PlotSpatialBuilder.Build(model, capture);
        }
    }
}
